const b = $input.first().json.body || $input.first().json || {};
const query = String(b.query || '').toLowerCase().trim();
const BRAND = $env.BRAND_NAME || "Tradesejon";
const MENTORS = $env.MENTORS_LIST || "Senior Lead Strategist, Mentor Alpha, Mentor Beta, Mentor Gamma, Mentor Delta";
const PLATFORMS = $env.SUPPORTED_PLATFORMS || "Webull, Interactive Brokers (IBKR), TradingView";

const FAQS = [
  { q: "مبتدئ في التداول / الفيديوهات", a: `في ${BRAND} بنبدأ معاك من الصفر بخطة تدريبية منظمة وتطبيق عملي لايف عشان تتقن استراتيجية الـ Hyper-Scalping خطوة بخطوة.` },
  { q: "ايه المتطلبات عشان ابدأ؟", a: "لابتوب أو كمبيوتر، إنترنت مستقر، والتفرغ لحضور الجلسات اللايف المباشرة." },
  { q: "رأس المال المطلوب للبدء؟", a: "تقدر تبدأ بمرونة من $100 إلى $500 مع إدارة صارمة لرأس المال (WIN BIG, win small, lose small)." },
  { q: "منصات وبرامج التداول المعتمدة؟", a: `ندعم رسمياً منصات: ${PLATFORMS}.` },
  { q: "أوقات الجلسات اليومية المباشرة؟", a: $env.LIVE_SESSION_SCHEDULE || "يومياً من الإثنين للجمعة الساعة 9:30 مساءً عبر Discord VIP و Zoom." },
  { q: "أسعار ورشة التداول الأوفلاين؟", a: `${$env.WORKSHOP_MEMBER_PRICE || '4,000'} جنيه ($74.39) للأعضاء، و ${$env.WORKSHOP_NONMEMBER_PRICE || '6,000'} جنيه ($111.59) لغير المشتركين.` },
  { q: "اشتراك مجتمع وسكانر الديسكورد؟", a: `$${$env.VIP_MONTHLY_USD || '45'} شهرياً عبر Whop شاملة قنوات الـ VIP وسكانر الصفقات اللحظي.` },
  { q: "جلسة المتابعة الخاصة 4 ساعات؟", a: `جلسة Online 1-on-1 لمدة 4 ساعات بقيمة $${$env.PRIVATE_SESSION_USD || '100'} شاملة مراجعة المحفظة والتطبيق المباشر.` },
  { q: "من هم الموجهين والمدربين؟", a: `فريق التوجيه المعتمد في ${BRAND}: ${MENTORS}.` },
  { q: "طريقة وأسلوب التداول؟", a: "استراتيجية الـ Hyper-Scalping بمبدأ WIN BIG, win small, lose small." },
  { q: "هل يوجد توصيات شراء وبيع مباشرة؟", a: "بنوفرلك تحليلات لايف ومناطق دخول احترافية وسكانر لحظي مع تدريبك على القرار المستقل." },
  { q: "كيفية تجديد الاشتراك أو الترقية؟", a: "عبر بوابة الدفع الرسمية Whop بشكل تلقائي بالكامل وبمرونة الإلغاء بأي وقت." },
  { q: "هل الديسكورد متصل بالتيليجرام؟", a: `نعم، منظومة ${BRAND} Omnichannel تربط الديسكورد والتيليجرام بشكل لحظي متزامن.` },
  { q: "ماذا أفعل لو واجهت مشكلة في الدفع؟", a: "تواصل مع بوت الدعم الفني أو افتح تذكرة في روم #pr-desk في الديسكورد." },
  { q: "هل متوفر شهادة بعد الورشة؟", a: `نعم، يحصل الخريج على شهادة إتمام البرنامج التدريبي المعتمد من ${BRAND}.` },
  { q: "هل التداول مناسب للموظفين؟", a: "نعم، جلساتنا المسائية الساعة 9:30 مساءً بتوقيت القاهرة تناسب جدول العمل اليومي." },
  { q: "كيف أحصل على رابط الجلسة المباشرة؟", a: "يرسل الرابط المشفر تلقائياً عبر البوت قبل بدء الجلسة بـ 15 دقيقة." }
];

const corpus = FAQS.map(f => ({ title: f.q, a: f.a, source: 'official_faq' }));

try {
  const fs = require('fs');
  const kbFile = (($env.KB_DIR || '/home/node/rag-knowledge-base') + '/custom_knowledge.json');
  if (fs.existsSync(kbFile)) {
    const parsed = JSON.parse(fs.readFileSync(kbFile, 'utf8'));
    const entries = Array.isArray(parsed) ? parsed : (parsed.entries || []);
    for (const e of entries) {
      if (e.content) corpus.push({ title: e.title || 'Custom KB', a: String(e.content).slice(0, 1200), source: 'custom_disk' });
    }
  }
} catch (e) {}

if ($env.MONGODB_URI) {
  try {
    const { MongoClient } = require('mongodb');
    const c = new MongoClient($env.MONGODB_URI);
    await c.connect();
    const docs = await c.db($env.MONGODB_DB || 'tradesejon_prod').collection('knowledge_chunks').find().sort({ updated_at: -1 }).limit(80).toArray();
    for (const d of docs) {
      if (d.text) corpus.push({ title: d.title || d.slug || 'Mongo KB', a: d.text, source: 'mongodb_chunk' });
    }
    await c.close();
  } catch (e) {}
}

const tokens = query.split(/\s+/).filter(t => t.length > 2);
const scored = corpus.map(item => {
  const hay = `${item.title} ${item.a}`.toLowerCase();
  let score = query && hay.includes(query) ? 5 : 0;
  for (const t of tokens) if (hay.includes(t)) score += 1;
  return { q: item.title, a: item.a, source: item.source, score };
}).filter(x => x.score > 0).sort((a, b) => b.score - a.score);

return [{ json: { ok: true, brand: BRAND, rag_hits: scored.length, top_context: scored.slice(0, 5) } }];

const b = $input.first().json.body || $input.first().json || {};
const title = String(b.title || 'Synced Knowledge Entry').trim();
const slug = String(b.slug || title.toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 48)).trim();
const content = String(b.content || b.text || '').trim();
const category = String(b.category || 'general').trim();
if (!content) return [{ json: { ok: false, error: 'Missing content field' } }];

let mongoOk = false;
let diskOk = false;

try {
  const fs = require('fs');
  const kbDir = $env.KB_DIR || '/home/node/rag-knowledge-base';
  const kbFile = kbDir + '/custom_knowledge.json';
  fs.mkdirSync(kbDir, { recursive: true });
  let existing = [];
  if (fs.existsSync(kbFile)) {
    const raw = JSON.parse(fs.readFileSync(kbFile, 'utf8'));
    existing = Array.isArray(raw) ? raw : (raw.entries || []);
  }
  const next = existing.filter(e => e.slug !== slug);
  next.unshift({ slug, title, category, content: content.slice(0, 32000), updated_at: new Date().toISOString() });
  fs.writeFileSync(kbFile, JSON.stringify({ updated_at: new Date().toISOString(), count: next.length, entries: next }, null, 2));
  diskOk = true;
} catch (e) {}

if ($env.MONGODB_URI) {
  try {
    const { MongoClient } = require('mongodb');
    const c = new MongoClient($env.MONGODB_URI);
    await c.connect();
    const db = c.db($env.MONGODB_DB || 'tradesejon_prod');
    await db.collection('kb_articles').updateOne({ slug }, { $set: { slug, title, category, content, updated_at: new Date() } }, { upsert: true });
    await c.close();
    mongoOk = true;
  } catch (e) {}
}

return [{ json: { ok: true, slug, title, synced: { diskOk, mongoOk }, timestamp: new Date().toISOString() } }];
